def extract(data, suffix, cfg, directory):
    result = dict(sections=[], warnings=[], attachments=[], artifacts=[], status="ready")

    def add(text, locator, modality="native"):
        # email.raw_items() can expose surrogate-escaped undecodable header bytes.
        # Keep a reversible printable representation and a gap, never lose the body.
        if any(0xD800 <= ord(c) <= 0xDFFF for c in text):
            result["warnings"].append(
                "Undecodable header/text bytes escaped in extracted representation; original bytes preserved"
            )
            text = text.encode("utf-8", errors="backslashreplace").decode("utf-8")
        result["sections"].append(dict(text=text, locator=locator, modality=modality))

    def artifact(name, content):
        result["artifacts"].append(dict(name=name, data=base64.b64encode(content).decode()))

    def child(name, content, part, mime):
        if len(result["attachments"]) >= cfg["max_attachments"]:
            gap = "Attachment count limit reached at " + part
            result["warnings"].append(gap)
            result["attachments"].append(dict(name=name, data=None, part=part, mime=mime, gap=gap))
            return
        result["attachments"].append(
            dict(name=name, data=base64.b64encode(content).decode(), part=part, mime=mime)
        )

    def decode(payload, charset="utf-8-sig"):
        try:
            return payload.decode(charset)
        except (UnicodeError, LookupError):
            result["warnings"].append("Invalid/unknown text encoding; replacement characters retained")
            return payload.decode("utf-8", errors="replace")

    def ocr(image):
        if cfg["ocr"] != "auto":
            raise ValueError("OCR disabled")
        p = subprocess.run(
            ["tesseract", str(image), "stdout", "-l", cfg["ocr_languages"]]
            + (["--tessdata-dir", cfg["tessdata"]] if cfg.get("tessdata") else []),
            capture_output=True,
            timeout=90,
        )
        if p.returncode:
            raise ValueError(p.stderr.decode(errors="replace")[-1000:])
        text = p.stdout.decode("utf-8")
        if not text.strip():
            result["warnings"].append("OCR returned no readable text")
        return text

    if suffix in (".txt", ".md"):
        encoding = "utf-16" if data.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8-sig"
        add(decode(data, encoding), {"kind": "text"})
    elif suffix == ".eml":
        msg = BytesParser(policy=policy.default).parsebytes(data)

        def visit(part, path, depth=0):
            if depth > cfg["max_attachment_depth"]:
                gap = "MIME nesting limit: " + path
                result["warnings"].append(gap)
                result["attachments"].append(
                    dict(
                        name="unexamined-mime-container.eml",
                        data=None,
                        part=path,
                        mime=part.get_content_type(),
                        gap=gap,
                    )
                )
                return
            for defect in part.defects:
                result["warnings"].append("MIME defect at " + path + ": " + str(defect))
            if part.get_content_type() == "message/rfc822":
                nested = part.get_payload()
                if isinstance(nested, list):
                    for j, message in enumerate(nested):
                        child(
                            part.get_filename() or "message.eml",
                            message.as_bytes(policy=policy.default),
                            f"{path}.{j}",
                            "message/rfc822",
                        )
                else:
                    result["warnings"].append("Unread embedded message at " + path)
            elif part.is_multipart():
                for i, sub in enumerate(part.iter_parts()):
                    visit(sub, f"{path}.{i}", depth + 1)
            else:
                payload = part.get_payload(decode=True) or b""
                mime = part.get_content_type()
                if (
                    part.get_filename()
                    or part.get_content_disposition() == "attachment"
                    or mime not in ("text/plain", "text/html")
                ):
                    suffixes = {"image/png": ".png", "image/jpeg": ".jpg", "application/pdf": ".pdf"}
                    child(part.get_filename() or ("part" + suffixes.get(mime, ".bin")), payload, path, mime)
                else:
                    text = decode(payload, part.get_content_charset() or "utf-8")
                    if mime == "text/html":
                        from bs4 import BeautifulSoup

                        artifact("mime-" + path + ".html", payload)
                        soup = BeautifulSoup(text, "html.parser")
                        for node in soup(["script", "style"]):
                            node.decompose()
                        text = soup.get_text("\n")
                        result["warnings"].append("HTML MIME body formatting and visual content not reviewed")
                    add(text, {"kind": "mime_body", "mime_part": path})

        for i, (key, value) in enumerate(msg.raw_items()):
            add(str(value), {"kind": "email_header", "header": key, "index": i, "mime_part": "0"})
        visit(msg, "0")
        if result["attachments"]:
            result["warnings"].append(
                "Decoded MIME children are derived representations; exact wire bytes remain in parent original"
            )
    elif suffix == ".docx":
        from docx import Document

        with zipfile.ZipFile(io.BytesIO(data)) as z:
            infos = z.infolist()
            if len(infos) > 20000 or sum(x.file_size for x in infos) > cfg["max_file_bytes"] * 8:
                raise ValueError("Office archive expansion limit")
            # Preserve raw XML, including table/revision structure, as a separate artifact.
            for name in sorted(z.namelist()):
                if name.startswith("word/") and name.endswith(".xml"):
                    artifact(name, z.read(name))
            for name in sorted(z.namelist()):
                if name.startswith("word/embeddings/") and not name.endswith("/"):
                    child(Path(name).name, z.read(name), "docx:" + name, "application/octet-stream")
            document = Document(io.BytesIO(data))
            # XML iteration includes tables, text boxes, footnotes, comments and deleted text.
            from lxml import etree

            for name in sorted(z.namelist()):
                if name.startswith("word/") and name.endswith(".xml"):
                    root = etree.fromstring(
                        z.read(name), parser=etree.XMLParser(resolve_entities=False, no_network=True)
                    )
                    for i, paragraph in enumerate(root.xpath('//*[local-name()="p"]')):
                        tokens = []
                        for node in paragraph.iter():
                            tag = etree.QName(node).localname
                            if tag in ("t", "delText"):
                                tokens.append(node.text or "")
                            elif tag == "tab":
                                tokens.append("\t")
                            elif tag in ("br", "cr"):
                                tokens.append("\n")
                        add("".join(tokens), {"kind": "docx", "part": name, "paragraph": i})
            artifact(
                "tables.json",
                json.dumps([[[c.text for c in r.cells] for r in t.rows] for t in document.tables]).encode(),
            )
        result["warnings"].append(
            "DOCX formatting, revisions, embedded media and field evaluation require original visual review"
        )
    elif suffix == ".pdf":
        from pypdf import PdfReader

        reader = PdfReader(io.BytesIO(data), strict=False)
        if reader.is_encrypted and not reader.decrypt(""):
            raise ValueError("Encrypted PDF")
        result["warnings"].append(
            "PDF visual content, layout and handwriting are not fully reviewed by text extraction"
        )
        for i, page in enumerate(reader.pages, 1):
            try:
                try:
                    text = page.extract_text(extraction_mode="layout") or ""
                except Exception as exc:
                    text = ""
                    result["warnings"].append(
                        f"Page {i}: native text failed; OCR/annotations still attempted: {exc}"
                    )
                method = "native"
                if not text.strip():
                    try:
                        target = directory / f"page-{i}"
                        p = subprocess.run(
                            [
                                "pdftoppm",
                                "-f",
                                str(i),
                                "-l",
                                str(i),
                                "-scale-to",
                                "3000",
                                "-singlefile",
                                "-png",
                                str(directory / "input"),
                                str(target),
                            ],
                            capture_output=True,
                            timeout=60,
                        )
                        if p.returncode:
                            raise ValueError("PDF rendering failed")
                        image = target.with_suffix(".png")
                        artifact(f"page-{i}.png", image.read_bytes())
                        text = ocr(image)
                        method = "ocr"
                    except Exception as exc:
                        result["warnings"].append(f"Page {i}: unread/OCR gap: {exc}")
                add(text, {"kind": "pdf", "page": i}, method)
                for j, annotation in enumerate(page.get("/Annots", [])):
                    obj = annotation.get_object()
                    for key in ("/Contents", "/T", "/V", "/Subj"):
                        if obj.get(key):
                            value = obj[key]
                            locator = {"kind": "pdf_annotation", "page": i, "annotation": j, "field": key}
                            if isinstance(value, str):
                                add(value, locator)
                            else:
                                # Signature dictionaries/binary values are not prose. Retain
                                # their representation separately instead of flooding review text.
                                name = f"page-{i}-annotation-{j}-{key[1:]}.json"
                                artifact(
                                    name,
                                    json.dumps({"locator": locator, "representation": repr(value)}).encode(),
                                )
                                result["warnings"].append(
                                    f"Non-text annotation retained as artifact {name}; semantics unreviewed"
                                )
            except Exception as exc:
                result["warnings"].append(f"Page {i}: extraction failed: {exc}")
        try:
            for name, values in reader.attachments.items():
                for i, value in enumerate(values):
                    child(name, value, f"pdf:{name}:{i}", "application/octet-stream")
        except Exception as exc:
            result["warnings"].append("PDF attachment enumeration failed: " + str(exc))
    else:
        from PIL import Image

        result["warnings"].append("Image OCR is fallible; visual content and handwriting remain unreviewed")
        with Image.open(io.BytesIO(data)) as img:
            for i in range(getattr(img, "n_frames", 1)):
                img.seek(i)
                target = directory / f"image-{i}.png"
                img.convert("RGB").save(target)
                artifact(target.name, target.read_bytes())
                try:
                    add(ocr(target), {"kind": "image", "frame": i}, "ocr")
                except Exception as exc:
                    result["warnings"].append(f"Frame {i}: OCR gap: {exc}")
    if result["warnings"]:
        result["status"] = "partial"
    return result


def main():
    from .isolation import deny_network

    deny_network()
    resource.setrlimit(resource.RLIMIT_AS, (2_000_000_000, 2_000_000_000))
    resource.setrlimit(resource.RLIMIT_CPU, (150, 150))
    resource.setrlimit(resource.RLIMIT_FSIZE, (500_000_000, 500_000_000))
    directory = Path(sys.argv[1])
    result = extract(
        (directory / "input").read_bytes(),
        sys.argv[2],
        json.loads((directory / "config.json").read_text()),
        directory,
    )
    (directory / "result.json").write_text(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

def call(self, stage, payload, schema):
    if stage != "discovery" or schema != _schema(payload) or _input_bytes(payload) > MAX_INPUT_BYTES:
        raise ValueError("Invalid discovery transport input")
    provider = _copy(schema)

    def adapt(node):
        if isinstance(node, dict):
            node.pop("uniqueItems", None)
            for value in node.values():
                adapt(value)
        elif isinstance(node, list):
            for value in node:
                adapt(value)

    adapt(provider)
    helper = self.adapter.worker
    # Separate stage keys prevent concurrent partitions sharing this worker
    # instance from replacing one another's bound schema.
    helper_stage = "discovery_" + payload["batch_id"]
    helper.schemas[helper_stage] = provider
    helper.trusted_instructions[helper_stage] = INSTRUCTIONS
    try:
        return helper.call(helper_stage, payload)
    except BaseException as exc:
        folder = getattr(exc, "call_directory", None)
        if folder is not None:
            response = Path(folder) / "response.json"
            receipt = Path(folder) / "receipt.json"
            events = Path(folder) / "events.jsonl"
            terminal = []
            if events.exists():
                for line in events.read_text(errors="replace").splitlines():
                    try:
                        event = json.loads(line)
                    except ValueError:
                        continue
                    if isinstance(event, dict) and event.get("type") in {"turn.completed", "turn.failed"}:
                        terminal.append(event)
            exc.discovery_terminal = bool(terminal)
            exc.discovery_blocked = not terminal or terminal[-1]["type"] != "turn.completed"
            exc.raw_output = dict(
                call_directory=str(folder),
                terminal_events=terminal,
                receipt=receipt.read_text(errors="replace") if receipt.exists() else None,
                response=response.read_text(errors="replace") if response.exists() else None,
            )
        raise

def page(self, snapshot, scope, rows, cursor=None, limit=100, key=lambda x: x["id"]):
    self.store.snapshot(snapshot)
    if not 1 <= limit <= 1000:
        raise ValueError("limit must be 1..1000")
    signature = sha(dump(scope))
    after = None
    if cursor:
        try:
            value = json.loads(base64.urlsafe_b64decode(cursor))
            if value["snapshot"] != snapshot or value["scope"] != signature:
                raise ValueError("Cursor scope/snapshot mismatch")
            after = value["after"]
        except Exception as exc:
            raise ValueError("Invalid cursor") from exc
    ordered = sorted(rows, key=key)
    total = len(ordered)
    selected = [r for r in ordered if after is None or key(r) > after]
    items = []
    used = 0
    for row in selected[:limit]:
        size = len(dump(row).encode())
        if used + size > 750000:
            if not items:
                raise ValueError("One result exceeds response budget; use bounded source/feature reads")
            break
        items.append(row)
        used += size
    nxt = (
        base64.urlsafe_b64encode(
            dump({"snapshot": snapshot, "scope": signature, "after": key(items[-1])}).encode()
        ).decode()
        if len(selected) > len(items)
        else None
    )
    manifest = self.store.manifest(snapshot)
    return dict(
        snapshot_id=snapshot,
        items=items,
        next_cursor=nxt,
        total=None if scope["kind"] == "inventory" and not manifest["inventory_complete"] else total,
        known_matches=total,
        remaining=max(0, len(selected) - len(items)),
        extraction_warnings={
            "count": sum(bool(d["warnings"]) for d in manifest["documents"]),
            "details": "inventory tool enumerates all document warnings without truncation",
        },
        scope=scope,
        inventory_complete=manifest["inventory_complete"],
    )

def inventory(self, snapshot_id=None, cursor=None, limit=100):
    snapshot = self.store.snapshot(snapshot_id)["id"]
    rows = []
    for document in self.store.manifest(snapshot)["documents"]:
        item = dict(document)
        for field in ("warnings", "artifacts"):
            values = document.get(field, [])
            item[field] = values[:8]
            item[field + "_remaining"] = max(0, len(values) - 8)
            if len(values) > 8:
                item[field + "_continuation"] = {
                    "tool": "document_details",
                    "snapshot_id": snapshot,
                    "document_version_id": document["document_version_id"],
                    "kind": field,
                }
        rows.append(item)
    return self.page(
        snapshot, {"kind": "inventory"}, rows, cursor, limit, key=lambda r: r["document_version_id"]
    )

def search(self, snapshot_id, query, mode="lexical", cursor=None, limit=100):
    if not query or len(query) > 4096:
        raise ValueError("Query must contain 1..4096 characters")
    if mode == "lexical":
        # Deliberately support a phrase only, not arbitrary FTS expression syntax.
        expression = '"' + query.replace('"', '""') + '"'
        self.store.snapshot(snapshot_id)
        name = fts_name(snapshot_id)
        rows = self.store.rows(
            f"""SELECT s.id,s.extraction_id,s.text,e.document_version_id,bm25({name}) score
            FROM {name} JOIN segments s ON s.id={name}.segment_id JOIN extractions e ON e.id=s.extraction_id
            JOIN snapshot_documents sd ON sd.extraction_id=e.id WHERE sd.snapshot_id=? AND {name} MATCH ?""",
            (snapshot_id, expression),
        )
        for row in rows:
            row["order_key"] = [row["score"], row["id"]]
        return self.page(
            snapshot_id,
            {
                "kind": "search",
                "mode": mode,
                "query": query,
                "grammar": "unicode61 phrase; case/diacritic folding; BM25",
            },
            rows,
            cursor,
            limit,
            key=lambda r: r["order_key"],
        )
    if mode != "literal":
        raise ValueError("mode must be lexical or literal")
    # Search canonical extraction, including strings crossing segment boundaries.
    rows = []
    for doc in self.store.rows(
        """SELECT e.* FROM snapshot_documents sd JOIN extractions e ON e.id=sd.extraction_id WHERE sd.snapshot_id=?""",
        (snapshot_id,),
    ):
        text = json.loads(self.store.get(doc["artifact_sha"]))["text"]
        segments = self.store.rows(
            "SELECT * FROM segments WHERE extraction_id=? ORDER BY ordinal", (doc["id"],)
        )
        pos = 0
        while (pos := text.find(query, pos)) >= 0:
            refs = []
            for seg in segments:
                lo, hi = max(pos, seg["char_start"]), min(pos + len(query), seg["char_end"])
                if hi > lo:
                    refs.append(
                        dict(
                            segment_id=seg["id"],
                            extraction_id=doc["id"],
                            start=lo - seg["char_start"],
                            end=hi - seg["char_start"],
                            quote=text[lo:hi],
                        )
                    )
            rows.append(
                dict(
                    id=doc["id"] + ":" + str(pos).zfill(16),
                    document_version_id=doc["document_version_id"],
                    sources=refs,
                    quote=query,
                )
            )
            pos += 1
    return self.page(
        snapshot_id,
        {
            "kind": "search",
            "mode": mode,
            "query": query,
            "absence_scope": "preserved extracted text only",
        },
        rows,
        cursor,
        limit,
    )

def related(self, snapshot_id, document_version_id, cursor=None, limit=100):
    """Ranked discovery, separate from complete exact-membership enumeration."""
    import math

    self.store.one(
        "SELECT * FROM (SELECT * FROM snapshot_documents UNION ALL SELECT * FROM snapshot_history) WHERE snapshot_id=? AND document_version_id=?",
        (snapshot_id, document_version_id),
    )
    rows = self.store.rows(
        """SELECT DISTINCT e.document_version_id,f.id feature_id,f.kind
        FROM snapshot_occurrences so JOIN occurrences o ON o.id=so.occurrence_id
        JOIN features f ON f.id=o.feature_id JOIN segments s ON s.id=o.segment_id
        JOIN extractions e ON e.id=s.extraction_id WHERE so.snapshot_id=? AND e.document_version_id!=?
        AND o.feature_id IN (SELECT o2.feature_id FROM occurrences o2 JOIN segments s2 ON s2.id=o2.segment_id
            JOIN snapshot_documents sd2 ON sd2.extraction_id=s2.extraction_id WHERE sd2.snapshot_id=? AND sd2.document_version_id=?)""",
        (snapshot_id, document_version_id, snapshot_id, document_version_id),
    )
    total = self.store.db.execute(
        "SELECT count(*) FROM snapshot_documents WHERE snapshot_id=?", (snapshot_id,)
    ).fetchone()[0]
    groups, frequencies = {}, {}
    for row in rows:
        fid = row["feature_id"]
        if fid not in frequencies:
            frequencies[fid] = self.store.db.execute(
                """SELECT count(DISTINCT sd.document_version_id) FROM occurrences o JOIN snapshot_occurrences so ON so.occurrence_id=o.id
                JOIN segments s ON s.id=o.segment_id JOIN snapshot_documents sd ON sd.extraction_id=s.extraction_id AND sd.snapshot_id=so.snapshot_id WHERE so.snapshot_id=? AND o.feature_id=?""",
                (snapshot_id, fid),
            ).fetchone()[0]
        tier = (
            1
            if row["kind"] in ("identifier", "original_blob", "message_id", "document_reference")
            else 2
            if row["kind"] == "paragraph"
            else 3
        )
        item = groups.setdefault(
            row["document_version_id"],
            {"id": row["document_version_id"], "tier": tier, "idf_rank": 0, "reasons": []},
        )
        item["tier"] = min(tier, item["tier"])
        item["idf_rank"] += math.log1p(total / frequencies[fid])
        item["reasons"].append(
            {"feature_id": fid, "kind": row["kind"], "document_frequency": frequencies[fid]}
        )
    for link in self.store.rows(
        """SELECT l.* FROM snapshot_links sl JOIN explicit_links l ON l.id=sl.link_id WHERE sl.snapshot_id=? AND (l.from_node=? OR l.to_node=?)""",
        (snapshot_id, document_version_id, document_version_id),
    ):
        other = link["to_node"] if link["from_node"] == document_version_id else link["from_node"]
        if not other:
            continue
        item = groups.setdefault(other, {"id": other, "tier": 0, "idf_rank": 0, "reasons": []})
        item["tier"] = 0
        item["reasons"].append(
            {"link_id": link["id"], "relationship": link["relation_type"], "status": link["status"]}
        )
    for item in groups.values():
        item["order_key"] = [item["tier"], -item["idf_rank"], item["id"]]
        item["reason_count"] = len(item["reasons"])
        item["reasons"] = item["reasons"][:8]
        item["remaining_reasons"] = max(0, item["reason_count"] - 8)
        item["evidence_tool"] = {
            "tool": "explain_connection",
            "left_document_id": document_version_id,
            "right_document_id": item["id"],
            "snapshot_id": snapshot_id,
        }
    return self.page(
        snapshot_id,
        {
            "kind": "ranked_related_preview",
            "document": document_version_id,
            "score_meaning": "ranking only, never relationship probability",
        },
        list(groups.values()),
        cursor,
        limit,
        key=lambda r: r["order_key"],
    )

def ocr_image(path: Path, languages: str, timeout: int = 180) -> str:
    exe = shutil.which("tesseract")
    if not exe:
        raise CorpusError("OCR needs Tesseract and the selected language packs.")
    p = subprocess.run([exe, str(path), "stdout", "-l", languages], capture_output=True, timeout=timeout)
    if p.returncode:
        raise CorpusError("Tesseract failed: " + p.stderr.decode("utf-8", "replace")[-1000:])
    return p.stdout.decode("utf-8", errors="strict")

def ocr_pdf_page(data: bytes, page: int, languages: str) -> str:
    exe = shutil.which("pdftoppm")
    if not exe:
        raise CorpusError("Scanned PDF OCR needs Poppler (pdftoppm) and Tesseract.")
    with tempfile.TemporaryDirectory(prefix="corpus-ocr-") as td:
        src = Path(td) / "source.pdf"
        src.write_bytes(data)
        base = Path(td) / "page"
        p = subprocess.run([exe, "-f", str(page), "-l", str(page), "-r", "180", "-scale-to", "4000", "-singlefile", "-png", str(src), str(base)], capture_output=True, timeout=180)
        if p.returncode:
            raise CorpusError("PDF rendering for OCR failed: " + p.stderr.decode("utf-8", "replace")[-1000:])
        return ocr_image(base.with_suffix(".png"), languages)

def extract(data: bytes, suffix: str, cfg: dict) -> dict:
    """Return all extractable text sections, explicit warnings, and attachments."""
    sections: list[dict] = []
    warnings: list[str] = []
    attachments: list[tuple[str, bytes]] = []

    def add(location: str, text: str, method: str = "native") -> None:
        # Preserve text, including whitespace, for reproducible source offsets.
        sections.append({"location": location, "text": text, "method": method})

    if suffix in TEXT_EXT:
        text, ws = decode_text(data, cfg["encoding"])
        warnings.extend(ws)
        add("text", text)
    elif suffix in (".html", ".htm"):
        text, ws = decode_text(data, cfg["encoding"])
        warnings.extend(ws)
        text, ws = html_text(text)
        warnings.extend(ws)
        add("HTML text", text)
    elif suffix == ".pdf":
        from pypdf import PdfReader
        reader = PdfReader(io.BytesIO(data), strict=False)
        if reader.is_encrypted and not reader.decrypt(""):
            raise CorpusError("Encrypted PDF requires a password; not extracted.")
        for i, page in enumerate(reader.pages, 1):
            try:
                text = page.extract_text(extraction_mode="layout") or ""
                resources = page.get("/Resources")
                resources = resources.get_object() if resources else {}
                xobjects = resources.get("/XObject")
                xobjects = xobjects.get_object() if xobjects else {}
                visual = any(obj.get_object().get("/Subtype") in ("/Image", "/Form") for obj in xobjects.values())
                method = "native"
                if len(re.sub(r"\W", "", text)) < 30 and visual:
                    if cfg["ocr"] == "auto":
                        try:
                            ocr = ocr_pdf_page(data, i, cfg["ocr_languages"])
                            if not ocr.strip():
                                raise CorpusError("OCR returned no text")
                            text = ocr
                            method = "ocr"
                            warnings.append(f"Page {i}: OCR text requires verification; pictures/handwriting may be missed.")
                        except Exception as exc:
                            warnings.append(f"Page {i}: UNREAD visual/scanned content: {exc}")
                    else:
                        warnings.append(f"Page {i}: UNREAD visual/scanned content; OCR disabled.")
                elif visual:
                    warnings.append(f"Page {i}: embedded image/form graphics not visually reviewed; extracted text only.")
                add(f"PDF page {i}", text, method)
                for j, ref in enumerate(page.get("/Annots", []), 1):
                    a = ref.get_object()
                    parts = [f"{k}: {a[k]}" for k in ("/T", "/Contents", "/V", "/Subj") if a.get(k)]
                    if parts:
                        add(f"PDF page {i}, annotation {j}", "\n".join(parts))
            except Exception as exc:
                add(f"PDF page {i}", "")
                warnings.append(f"Page {i}: UNREAD extraction error: {exc}")
        try:
            for name, payloads in reader.attachments.items():
                for payload in payloads:
                    attachments.append((str(name), payload))
        except Exception as exc:
            warnings.append(f"PDF attachments could not be enumerated: {exc}")
    elif suffix == ".docx":
        with checked_zip(data, cfg["max_file_bytes"]) as z:
            names = z.namelist()
            wanted = ["word/document.xml"] + sorted(n for n in names if re.fullmatch(r"word/(header\d+|footer\d+|footnotes|endnotes|comments)\.xml", n))
            for name in wanted:
                if name not in names:
                    continue
                root = xml_root(z.read(name))
                for i, text in enumerate(word_paragraphs(root), 1):
                    add(f"DOCX {Path(name).stem}, paragraph {i}", text)
                if any(localname(n.tag) in {"drawing", "pict", "object", "altChunk", "ins", "del"} for n in root.iter()):
                    warnings.append(f"{name}: images/embedded content or tracked changes present; review original formatting and revision semantics.")
            if any(n.startswith("word/embeddings/") for n in names):
                warnings.append("DOCX contains embedded objects; these are not recursively extracted.")
    elif suffix in (".xlsx", ".xlsm"):
        from openpyxl import load_workbook
        with checked_zip(data, cfg["max_file_bytes"]) as z:
            if any(n.startswith(("xl/media/", "xl/charts/", "xl/embeddings/")) for n in z.namelist()):
                warnings.append("Workbook visual charts/images/embedded objects are not interpreted.")
        workbook = load_workbook(io.BytesIO(data), read_only=False, data_only=False, keep_links=False)
        values = load_workbook(io.BytesIO(data), read_only=True, data_only=True, keep_links=False)
        try:
            for sheet in workbook.worksheets:
                if sheet.max_row * sheet.max_column > 2_000_000:
                    warnings.append(f"UNREAD sheet {sheet.title}: cell grid exceeds safety limit.")
                    continue
                add(f"sheet {sheet.title}", f"Sheet: {sheet.title}; visibility: {sheet.sheet_state}")
                for row in sheet.iter_rows():
                    cells = []
                    for cell in row:
                        if cell.value is None and not cell.comment:
                            continue
                        val = str(cell.value) if cell.value is not None else ""
                        if cell.data_type == "f":
                            cached = values[sheet.title][cell.coordinate].value
                            val += " [cached value: " + str(cached) + "]"
                            if cached is None:
                                warnings.append(f"{sheet.title}!{cell.coordinate}: formula has no cached result; not recalculated.")
                        if cell.comment:
                            val += " [comment: " + cell.comment.text + "]"
                        if cell.hyperlink:
                            val += " [link: " + str(cell.hyperlink.target) + "]"
                        cells.append(f"{cell.coordinate}: {val}")
                    if cells:
                        add(f"sheet {sheet.title}, row {row[0].row}", " | ".join(cells))
        finally:
            workbook.close()
            values.close()
    elif suffix == ".pptx":
        with checked_zip(data, cfg["max_file_bytes"]) as z:
            names = z.namelist()
            wanted = sorted((n for n in names if re.fullmatch(r"ppt/(slides/slide\d+|notesSlides/notesSlide\d+)\.xml", n)), key=lambda s: ("notes" in s, int(re.search(r"(\d+)\.xml", s)[1])))
            for name in wanted:
                root = xml_root(z.read(name))
                text = "\n".join("".join(t.text or "" for t in p.iter() if localname(t.tag) == "t") for p in root.iter() if localname(p.tag) == "p")
                add(f"PPTX {Path(name).stem}", text)
            if any(n.startswith(("ppt/media/", "ppt/charts/", "ppt/embeddings/", "ppt/diagrams/")) for n in names):
                warnings.append("Slides contain visual/embedded material not interpreted by text extraction.")
    elif suffix == ".eml":
        msg = email.message_from_bytes(data, policy=email.policy.default)
        add("email headers", "\n".join(f"{k}: {v}" for k, v in msg.items()))
        def mime_parts(part):
            if part.get_content_type() == "message/rfc822":
                yield part
            elif part.is_multipart():
                for child in part.iter_parts():
                    yield from mime_parts(child)
            else:
                yield part
        for i, part in enumerate(mime_parts(msg), 1):
            if part.get_content_type() == "message/rfc822":
                nested = part.get_payload()
                if isinstance(nested, list):
                    for j, m in enumerate(nested, 1):
                        attachments.append((part.get_filename() or f"forwarded-{i}-{j}.eml", m.as_bytes()))
                continue
            if part.is_multipart():
                continue
            payload = part.get_payload(decode=True) or b""
            name = part.get_filename()
            if name or part.get_content_disposition() == "attachment" or part.get_content_maintype() != "text":
                attachments.append((name or f"part-{i}" + {"image/png": ".png", "image/jpeg": ".jpg", "application/pdf": ".pdf"}.get(part.get_content_type(), ".bin"), payload))
                continue
            charset = part.get_content_charset()
            text, ws = decode_text(payload, charset or cfg["encoding"])
            warnings.extend(ws)
            if part.get_content_type() == "text/html":
                text, ws = html_text(text)
                warnings.extend(ws)
            add(f"email body part {i}", text)
        if msg.defects:
            warnings.append("Email parser reported defects: " + str(msg.defects))
    elif suffix in IMAGE_EXT:
        if cfg["ocr"] != "auto":
            raise CorpusError("Image requires OCR; initialize with --ocr auto or provide a transcription.")
        with tempfile.TemporaryDirectory(prefix="corpus-image-") as td:
            path = Path(td) / ("image" + suffix)
            path.write_bytes(data)
            text = ocr_image(path, cfg["ocr_languages"])
        if not text.strip():
            raise CorpusError("Image OCR returned no text; no visual interpretation was performed.")
        add("image OCR", text, "ocr")
        warnings.append("OCR is text-only and fallible; non-text visual information is not reviewed.")
    else:
        raise CorpusError(f"Unsupported extension {suffix or '(none)'}")
    return {"sections": sections, "warnings": sorted(set(warnings)), "attachments": attachments}

def page(self, snapshot, scope, rows, cursor=None, limit=100, key=lambda x: x["id"]):
    if self._request is None:
        return super().page(snapshot, scope, rows, cursor, limit, key)
    ordered = sorted(rows, key=key)
    manifest = self.store.manifest(snapshot)
    self._cached = {
        "request": self._request,
        "snapshot": snapshot,
        "scope": scope,
        "signature": sha(dump(scope)),
        "rows": ordered,
        "keys": [key(r) for r in ordered],
        "warnings": sum(bool(d["warnings"]) for d in manifest["documents"]),
        "inventory_complete": manifest["inventory_complete"],
    }
    self.materializations += 1
    return self._page(cursor, limit)

def _page(self, cursor, limit):
    c = self._cached
    self.store.snapshot(c["snapshot"])
    if not 1 <= limit <= 1000:
        raise ValueError("limit must be 1..1000")
    start = 0
    if cursor:
        try:
            value = json.loads(base64.urlsafe_b64decode(cursor))
            if value["snapshot"] != c["snapshot"] or value["scope"] != c["signature"]:
                raise ValueError("Cursor scope/snapshot mismatch")
            start = bisect_right(c["keys"], value["after"])
        except Exception as exc:
            raise ValueError("Invalid cursor") from exc
    items = []
    used = 0
    for row in c["rows"][start : start + limit]:
        size = len(dump(row).encode())
        if used + size > 750000:
            if not items:
                raise ValueError("One result exceeds response budget; use bounded source/feature reads")
            break
        items.append(row)
        used += size
    remaining = len(c["rows"]) - start - len(items)
    cursor = (
        base64.urlsafe_b64encode(
            dump(
                {
                    "snapshot": c["snapshot"],
                    "scope": c["signature"],
                    "after": c["keys"][start + len(items) - 1],
                }
            ).encode()
        ).decode()
        if remaining
        else None
    )
    return dict(
        snapshot_id=c["snapshot"],
        items=copy.deepcopy(items),
        next_cursor=cursor,
        total=len(c["rows"]),
        known_matches=len(c["rows"]),
        remaining=remaining,
        extraction_warnings={
            "count": c["warnings"],
            "details": "inventory tool enumerates all document warnings without truncation",
        },
        scope=c["scope"],
        inventory_complete=c["inventory_complete"],
    )

def neighbours(self, snapshot_id, node_id, relation_types=None, cursor=None, limit=100):
    request = dump([snapshot_id, node_id, relation_types])
    if self._cached is not None and self._cached["request"] == request:
        self.cache_hits += 1
        return self._page(cursor, limit)
    self._cached = None
    self._request = request
    try:
        return super().neighbours(snapshot_id, node_id, relation_types, cursor, limit)
    finally:
        self._request = None
